public static partial class RuleTests {
 static void EffectsLevels(){Check(EffectSettings.ParsePreferences("theme=codex\neffects=all\n")==EffectLevel.High,"Legacy all migrates to high");Check(EffectSettings.ParsePreferences("effects=off")==EffectLevel.Off&&EffectSettings.ParsePreferences("")==EffectLevel.Off,"Legacy off and absent option remain off");foreach(var level in new[]{EffectLevel.Off,EffectLevel.Low,EffectLevel.High})Check(EffectSettings.ParsePreferences("effects="+EffectSettings.PreferenceValue(level))==level,"Effect level preference roundtrip");bool rejected=false;try{EffectSettings.FromWire(3);}catch(InvalidDataException){rejected=true;}Check(rejected,"Invalid remote effect level is rejected");
  var g=Game();g.SetAnimationEffects(EffectLevel.Low);Check(g.EntranceAnimationsEnabled&&!g.HighAnimationsEnabled,"Low enables small effects but not high timelines");g.Play(0,Hand(g,"EX1_279"),new MatchTarget(1));Check(g.Players[1].Health==20&&!g.SpellImpactPending&&!g.AnimationPlaying,"Low Pyroblast resolves immediately without a fire timeline");g=Game();g.SetAnimationEffects(EffectLevel.Low);g.Summon(0,"VAN_NEW1_030");Check(!g.AnimationPlaying,"Deathwing does not gate at low");g=Game();g.SetAnimationEffects(EffectLevel.High);g.Summon(0,"VAN_NEW1_030");Check(g.AnimationPlaying,"Deathwing gates at high");
  g=Game();g.SetAnimationEffects(EffectLevel.Low);g.Players[0].ClassId="ROGUE";g.CardsPlayed=5;g.Play(0,Hand(g,"EX1_613"));Check(g.AnimationPlaying,"Edwin stays a low-tier entrance effect");var host=new LanHostGame(catalog,matchRules.TrainingDeck("MAGE"),matchRules.TrainingDeck("WARRIOR"),4,0);host.SetPresentation(0,EffectLevel.Low);host.SetPresentation(1,EffectLevel.Off);Check(host.Game.EntranceAnimationsEnabled&&!host.Game.HighAnimationsEnabled,"Low plus off does not enable high animation waits");host.SetPresentation(1,EffectLevel.High);Check(host.Game.HighAnimationsEnabled,"One high peer enables the shared high timeline");host.SetPresentation(1,EffectLevel.Low);Check(!host.Game.HighAnimationsEnabled,"Dropping remote level only disables future high timelines");Check(new LanMessage{EffectsLevel=1,FullEffectsEnabled=true}.ReadEffects()==EffectLevel.Low&&new LanMessage{FullEffectsEnabled=true}.ReadEffects()==EffectLevel.High,"Explicit tier takes priority while legacy message remains compatible");
 }
